24	function sanitizeSvgBuffer(input: Buffer): Buffer | null {
25	  const raw = input.toString("utf8").trim();
26	  if (!raw) return null;
27	
28	  const baseDom = new JSDOM("");
29	  const domPurify = createDOMPurify(
30	    baseDom.window as unknown as Parameters<typeof createDOMPurify>[0],
31	  );
32	  domPurify.addHook("uponSanitizeAttribute", (_node, data) => {
33	    const attrName = data.attrName.toLowerCase();
34	    const attrValue = (data.attrValue ?? "").trim();
35	
36	    if (attrName.startsWith("on")) {
37	      data.keepAttr = false;
38	      return;
39	    }
40	
41	    if ((attrName === "href" || attrName === "xlink:href") && attrValue && !attrValue.startsWith("#")) {
42	      data.keepAttr = false;
43	    }
44	  });
45	
46	  let parsedDom: JSDOM | null = null;
47	  try {
48	    const sanitized = domPurify.sanitize(raw, {
49	      USE_PROFILES: { svg: true, svgFilters: true, html: false },
50	      FORBID_TAGS: ["script", "foreignObject"],
51	      FORBID_CONTENTS: ["script", "foreignObject"],
52	      RETURN_TRUSTED_TYPE: false,
53	    });
54	
55	    parsedDom = new JSDOM(sanitized, { contentType: SVG_CONTENT_TYPE });
56	    const document = parsedDom.window.document;
57	    const root = document.documentElement;
58	    if (!root || root.tagName.toLowerCase() !== "svg") return null;
59	
60	    for (const el of Array.from(root.querySelectorAll("script, foreignObject"))) {
61	      el.remove();
62	    }
63	    for (const el of Array.from(root.querySelectorAll("*"))) {
64	      for (const attr of Array.from(el.attributes)) {
65	        const attrName = attr.name.toLowerCase();
66	        const attrValue = attr.value.trim();
67	        if (attrName.startsWith("on")) {
68	          el.removeAttribute(attr.name);
69	          continue;
70	        }
71	        if ((attrName === "href" || attrName === "xlink:href") && attrValue && !attrValue.startsWith("#")) {
72	          el.removeAttribute(attr.name);
73	        }
74	      }
75	    }
76	
77	    const output = root.outerHTML.trim();
78	    if (!output || !/^<svg[\s>]/i.test(output)) return null;
79	    return Buffer.from(output, "utf8");
80	  } catch {
81	    return null;
82	  } finally {
83	    parsedDom?.window.close();
84	    baseDom.window.close();
85	  }
86	}
