155	/**
156	 * Normalize a local path that may be a Windows path into a WSL-compatible path.
157	 *
158	 * - Windows paths (e.g., "C:\\Users\\...") are converted via `wslpath -u`.
159	 * - Paths already starting with `/mnt/` or `/` are returned as-is.
160	 */
161	async function normalizeLocalPath(rawPath: string): Promise<string> {
162	  // Already a POSIX path (WSL or native Linux)
163	  if (rawPath.startsWith("/")) {
164	    return rawPath;
165	  }
166	
167	  // Windows path detection: C:\ or C:/ pattern
168	  if (/^[A-Za-z]:[\\/]/.test(rawPath)) {
169	    try {
170	      const { stdout } = await execFileAsync("wslpath", ["-u", rawPath]);
171	      return stdout.trim();
172	    } catch (err) {
173	      logger.warn({ err, rawPath }, "wslpath conversion failed; using path as-is");
174	      return rawPath;
175	    }
176	  }
177	
