187	 * Keeps the hot-install and init-time paths at parity so an adapter installed
188	 * via `POST /api/adapters/install` has the same shape in the registry as the
189	 * same adapter loaded on the next server restart.
190	 */
191	function registerWithSessionManagement(adapter: ServerAdapterModule): void {
192	  registerServerAdapter(resolveExternalAdapterRegistration(adapter));
193	}
