287	    const body = await ctx.json<AdapterInstallRequest>();
288	    const { packageName, isLocalPath = false, version } = body;
289	
290	    if (!packageName || typeof packageName !== "string") {
291	      return Response.json({ error: "packageName is required and must be a string." }, { status: 400 });
292	    }
