294	    // Strip version suffix if the UI sends "pkg@1.2.3" instead of separating it
295	    let canonicalName = packageName;
296	    let explicitVersion = version;
297	    const versionSuffix = packageName.match(/@(\d+\.\d+\.\d+.*)$/);
298	    if (versionSuffix) {
299	      const lastAtIndex = packageName.lastIndexOf("@");
300	      if (lastAtIndex > 0 && !explicitVersion) {
301	        canonicalName = packageName.slice(0, lastAtIndex);
302	        explicitVersion = versionSuffix[1];
303	      }
304	    }
305	
306	    try {
307	      let installedVersion: string | undefined;
308	      let moduleLocalPath: string | undefined;
309	
310	      if (!isLocalPath) {
311	        const pluginsDir = getAdapterPluginsDir();
312	        const spec = explicitVersion ? `${canonicalName}@${explicitVersion}` : canonicalName;
313	
314	        logger.info({ spec, pluginsDir }, "Installing adapter package via npm");
315	
316	        await execFileAsync("npm", ["install", "--no-save", spec], {
317	          cwd: pluginsDir,
318	          timeout: 120_000,
319	        });
