321	        // TODO(cloudflare): reading package.json from the npm install directory
322	        // uses node:fs/promises at request time. For Workers compatibility the
323	        // installed version should be persisted to the DB by the install job and
324	        // read from there rather than from the local filesystem.
325	        try {
326	          const pkgJsonPath = path.join(pluginsDir, "node_modules", canonicalName, "package.json");
327	          const pkgContent = await import("node:fs/promises");
328	          const pkgRaw = await pkgContent.readFile(pkgJsonPath, "utf-8");
329	          const pkg = JSON.parse(pkgRaw);
330	          const v = pkg.version;
331	          installedVersion =
