57	    const root = document.documentElement;
58	    if (!root || root.tagName.toLowerCase() !== "svg") return null;
59	
60	    for (const el of Array.from(root.querySelectorAll("script, foreignObject"))) {
61	      el.remove();
62	    }
63	    for (const el of Array.from(root.querySelectorAll("*"))) {
64	      for (const attr of Array.from(el.attributes)) {
