335	        }
336	      } else {
337	        moduleLocalPath = path.resolve(await normalizeLocalPath(packageName));
338	        // TODO(cloudflare): reading package.json from a local-path adapter
339	        // directory uses node:fs/promises at request time. For Workers
340	        // compatibility the version should be captured during the install step
341	        // and stored in the database rather than read from disk at request time.
342	        try {
343	          const pkgRaw = await readFile(path.join(moduleLocalPath, "package.json"), "utf-8");
344	          const v = JSON.parse(pkgRaw).version;
345	          if (typeof v === "string" && v.trim().length > 0) {
346	            installedVersion = v.trim();
347	          }
348	        } catch {
349	          // leave installedVersion undefined if package.json is missing
350	        }
351	      }
352	
353	      const adapterModule = await loadExternalAdapterPackage(canonicalName, moduleLocalPath);
354	
355	      if (BUILTIN_ADAPTER_TYPES.has(adapterModule.type)) {
356	        return Response.json({
357	          error: `Adapter type "${adapterModule.type}" is a built-in adapter and cannot be overwritten.`,
358	        }, { status: 409 });
359	      }
360	
361	      const existing = findServerAdapter(adapterModule.type);
362	      const isReinstall = existing !== null;
363	      if (existing) {
364	        unregisterServerAdapter(adapterModule.type);
365	        logger.info({ type: adapterModule.type }, "Unregistered existing adapter for replacement");
366	      }
367	
368	      registerWithSessionManagement(adapterModule);
369	
370	      const record: AdapterPluginRecord = {
371	        packageName: canonicalName,
372	        localPath: moduleLocalPath,
373	        version: installedVersion ?? explicitVersion,
374	        type: adapterModule.type,
375	        installedAt: new Date().toISOString(),
376	      };
377	      addAdapterPlugin(record);
378	
379	      logger.info(
380	        { type: adapterModule.type, packageName: canonicalName },
381	        "External adapter installed and registered",
382	      );
383	
384	      return Response.json({
385	        type: adapterModule.type,
386	        packageName: canonicalName,
387	        version: installedVersion ?? explicitVersion,
388	        installedAt: record.installedAt,
